input.command:
cd apps/worker/migrations && python3 - <<'EOF'
import json, glob, os

ids = {}
for f in glob.glob("*/snapshot.json"):
    name = os.path.basename(os.path.dirname(f))
    data = json.load(open(f))
    ids[name] = data

# Build parent mapping
parents = {}
for name, data in ids.items():
    parents[name] = data["prevIds"]

# Detect dangling prevIds (references to ids that don't exist)
all_ids = {data["id"] for data in ids.values()}
refs = {}  # id -> list of children
for name, data in ids.items():
    for p in data["prevIds"]:
        if p == "00000000-0000-0000-0000-000000000000":
            continue
        if p not in all_ids:
            print(f"DANGLING: {name} prevIds -> {p} (no such snapshot)")
        refs.setdefault(p, []).append(name)

# Heads: snapshots whose id is never referenced
heads = [n for n, data in ids.items() if data["id"] not in refs]
print("HEADS:", heads)

# Branches: ids referenced by more than one child
for p, children in refs.items():
    if len(children) > 1:
        print(f"BRANCH: {p} referenced by {children}")

# Chain traversal from head
chain = []
cur = heads[0] if len(heads) == 1 else None
while cur:
    chain.append(cur)
    data = ids[cur]
    nxt = None
    for c, d in ids.items():
        if data["id"] in d["prevIds"]:
            nxt = c
            break
    if nxt == cur: break
    cur = nxt
print("FULL CHAIN length:", len(chain))
print("All snapshots:", len(ids))
print("Chain covers all:", set(chain) == set(ids))

# versions and table counts
for name, data in ids.items():
    n_tables = len([d for d in data["ddl"] if d.get("entityType") == "tables"])
    print(f"{name}: version={data['version']} tables={n_tables}")
EOF

